def candidate(grid, k):
    n = len(grid)
    paths = []

    def backtrack(row, col, path):
        if len(path) == k:
            paths.append(path)
            return
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nr, nc = row + dr, col + dc
            if 0 <= nr < n and 0 <= nc < n:
                backtrack(nr, nc, path + [grid[nr][nc]])

    for i in range(n):
        for j in range(n):
            backtrack(i, j, [grid[i][j]])

    return min(paths)

